def clean(df):
    df = df.copy()

    for col in ['species', 'island', 'sex']:
        if col in df.columns:
            df[col] = df[col].astype('string').str.strip()

    if 'species' in df.columns:
        df['species'] = df['species'].str.title()

    if 'island' in df.columns:
        df['island'] = df['island'].replace({
            'Dram': 'Dream',
            'Torgerson': 'Torgersen'
        })

    if 'sex' in df.columns:
        df['sex'] = df['sex'].str.lower()

    if 'flipper_length_mm' in df.columns:
        df['flipper_length_mm'] = pd.to_numeric(
            df['flipper_length_mm'].astype(str).str.replace(',', '', regex=False),
            errors='coerce'
        )

    if 'body_mass_g' in df.columns:
        df['body_mass_g'] = pd.to_numeric(
            df['body_mass_g'].astype(str).str.replace(',', '', regex=False),
            errors='coerce'
        )

    df = df.drop_duplicates()
    return df


def answer(df):
    d = clean(df)
    d = d.dropna(subset=['species', 'flipper_length_mm'])
    result = d.groupby('species')['flipper_length_mm'].mean().to_dict()
    return {str(k): float(v) for k, v in result.items()}
